var n=`0558-mutabbaq-samak`;var o=`world-0558`;var t=`KW`;var a=`western-asia`;var r=4;var s=91;var u={en:`Mutabbaq Samak`,ua:`Риба мутаббак самак`};var l={en:`A traditional dish from Kuwait, centered on sea bass, lemon juice, basmati rice, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Кувейт. Основні складники: сібас, лимонний сік, рис басматі, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`sea-bass`,900,`g`],[`lemon-juice`,50,`ml`],[`ground-turmeric`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`sunflower-oil`,70,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 25 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 25 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`basmati-rice`,430,`g`],[`water`,800,`ml`],[`ground-cardamom`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`yellow-onion`,160,`g`]]}];var d={slug:n,id:o,country:`KW`,region:a,servings:4,minutes:91,title:u,text:l,steps:m};export{t as country,d as default,o as id,s as minutes,a as region,r as servings,n as slug,m as steps,l as text,u as title};